 "content": "def transform(grid):
    """Highlight the 1-colored alternating stripe in the pattern."""
    out=[r[:] for r in grid]
    # The examples color every other foreground pixel in a repeated horizontal
    # stripe with 1. Look for a multi-row full run of the foreground color and
    # highlight alternating positions in the corresponding rows beneath it.
    bg=max(set(v for row in grid for v in row), key=lambda x: sum(row.count(x) for row in grid))
    colors=[v for row in grid for v in row if v!=bg]
    if not colors: return out
    fg=max(set(colors),key=colors.count)
    h,w=len(grid),len(grid[0])
    for r in range(h-2):
        # A long solid bar in this row identifies a repeated motif.
        runs=[]; c=0
        while c<w:
            if grid[r][c]==fg:
                a=c
                while c<w and grid[r][c]==fg: c+=1
                if c-a>=6: runs.append((a,c))
            else: c+=1
        for a,b in runs:
            for rr in (r+1,r+2):
                for cc in range(a,b):
                    if grid[rr][cc]==fg and (cc-a)%2==1:
                        out[rr][cc]=1
    return out
